script:
frappe.ui.form.on('Benefits SEH', {
    onload: function(frm) {
        // ตั้งค่า default ปี พ.ศ.
        const currentYearBE = new Date().getFullYear() + 543;
        if (!frm.doc.yearly) {
            frm.set_value('yearly', currentYearBE.toString());
        }
    },

    fullname: function(frm) {
        frappe.timeout(0.3).then(() => {
            if (frm.doc.employee_id) {
                frappe.call({
                    method: "erpnext.benefits_seh.get_previous_welfare_rights",
                    args: {
                        employee_id: frm.doc.employee_id,
                        current_docname: frm.doc.name || '',
                        amount: frm.doc.amount || 0  // ส่ง amount ไปด้วย
                    },
                    callback: function(r) {
                        if (r.message) {
                            const remaining = flt(r.message.total_remaining_welfare_rights || 0);
                            frm.set_value('total_remaining_welfare_rights', remaining);

                        }
                    }
                });
            }
        });
    }
});


frappe.ui.form.on('Benefits SEH', {
    validate: function(frm) {
        const remaining = flt(frm.doc.total_remaining_welfare_rights || 0);
        if (remaining === 0) {
            frappe.msgprint({
                title: __('ไม่สามารถบันทึกได้'),
                message: __('สิทธิ์สวัสดิการคงเหลือจำนวน 0 บาท ไม่สามารถใชัสิทธิ์ได้'),
                indicator: 'red'
            });
            frappe.validated = false;  // ❗ หยุดการบันทึก
        }
    }
});



frappe.ui.form.on('Benefits SEH', {
    amount_rights_used: function(frm) {
        calculate_remaining_rights(frm);
    }
});

function calculate_remaining_rights(frm) {
    const total = flt(frm.doc.total_remaining_welfare_rights || 0);
    const used = flt(frm.doc.amount_rights_used || 0);

    let remaining = total - used;
    let difference = 0;

    if (remaining < 0) {
        difference = Math.abs(remaining);  // หรือ: used - total
        remaining = 0;
    }

    frm.set_value('remaining_welfare_rights', remaining);
    frm.set_value('difference_paid', difference);
}
